<?php
if(!defined('ABSPATH')){exit;}
/** Dedicated local agent CLI, kept separate from the legacy design-core command. */
class Design_Core_Elementor_Design_Agent_CLI{public function status(){WP_CLI::print_value((new Design_Core_Elementor_Design_Agent_Service())->capabilities());}public function plan($args,$assoc){$brief=$assoc['brief']??implode(' ',$args);if(!$brief)WP_CLI::error('Provide --brief="...".');$r=(new Design_Core_Elementor_Design_Agent_Service())->plan_design($brief,array('product_type'=>$assoc['product-type']??'','mode'=>$assoc['mode']??'light','reference_target'=>$assoc['reference']??''));if(is_wp_error($r))WP_CLI::error($r->get_error_message());WP_CLI::print_value($r);}public function quality($args,$assoc){$id=(int)($assoc['page-id']??($args[0]??0));if($id<1)WP_CLI::error('Provide --page-id=<id>.');$r=(new Design_Core_Elementor_Design_Agent_Service())->quality($id,$assoc['reference']??'',$assoc['candidate']??'',array('target_similarity'=>(float)($assoc['target']??.95),'interactive'=>!empty($assoc['interactive'])));if(is_wp_error($r))WP_CLI::error($r->get_error_message());WP_CLI::print_value($r);}public function visual_feedback($args,$assoc){if(count($args)<2)WP_CLI::error('Provide reference target and candidate target.');$r=(new Design_Core_Elementor_Visual_Feedback_Engine())->evaluate_targets($args[0],$args[1],array('page_id'=>(int)($assoc['page-id']??0),'target_similarity'=>(float)($assoc['target']??.95)));if(is_wp_error($r))WP_CLI::error($r->get_error_message());WP_CLI::print_value($r);}public function visual_correct($args,$assoc){if(count($args)<2||empty($assoc['confirm']))WP_CLI::error('Provide reference, candidate and --confirm=1.');$id=(int)($assoc['page-id']??0);if($id<1)WP_CLI::error('Provide --page-id=<id>.');$r=(new Design_Core_Elementor_Visual_Correction_Service())->run($args[0],$args[1],max(1,min(5,(int)($assoc['iterations']??4))),(float)($assoc['target']??.95),array('page_id'=>$id));if(is_wp_error($r))WP_CLI::error($r->get_error_message());WP_CLI::print_value($r);}}
if(defined('WP_CLI')&&WP_CLI&&class_exists('WP_CLI'))WP_CLI::add_command('design-core-agent','Design_Core_Elementor_Design_Agent_CLI');
